public static BridgeResponse getBubbleStart() {
    final BridgeResponse reply = new BridgeResponse();
    ByteBuffer ackMessage = ByteBuffer.allocate(3);
    ackMessage.put(0, (byte) 0x05);
    ackMessage.put(1, (byte) 0x01);
    ackMessage.put(2, patchInfoByte[0]);//patchInfo first byte support 0xDF(libre1) and 0x70 (libre pro/h)
    reply.add(ackMessage);
    return reply;
}
